export const DEFAULT_IDLE_MS = 15 * 60_000;
export const SENSITIVE_IDLE_MS = 5 * 60_000;
export const IDLE_WARNING_MS = 60_000;
// Listen to user input, not scroll events generated by chat auto-scrolling.
const INPUT_EVENTS = ["mousemove", "mousedown", "keydown", "touchstart", "touchmove", "wheel", "click"];
export const idleStorageKeys = userId => ({
  activity: `coptrax:idle:${userId}:activity`, warning: `coptrax:idle:${userId}:warning`,
});
function browserStorage() {
  try { return window.localStorage; } catch { return null; }
}

/** One shared activity deadline per user/browser, with disposable per-tab timers. */
export function createSessionIdle({ userId, timeoutMs = DEFAULT_IDLE_MS, onWarning, onExpire,
  storage = browserStorage(), target = window, visibility = document,
  now = Date.now, setTimer = setTimeout, clearTimer = clearTimeout }) {
  const keys = idleStorageKeys(userId);
  let lastActivity = null, localWarning = null, timer, stopped = true, expired = false, lastInput = -Infinity;
  let lastNotice = "";
  const read = key => { try { return JSON.parse(storage.getItem(key)); } catch { return null; } };
  const write = (key, value) => { try { storage.setItem(key, JSON.stringify(value)); } catch { /* Memory fallback still enforces this tab's timeout. */ } };
  const remove = key => { try { storage.removeItem(key); } catch { /* Storage may be unavailable. */ } };
  function notice(show, seconds = 60) {
    const signature = `${show}:${seconds}`;
    if (lastNotice !== signature) { lastNotice = signature; onWarning({ show, seconds }); }
  }
  function snapshot() {
    const saved = read(keys.activity);
    if (Number.isFinite(saved?.at) && saved.at >= 0) lastActivity = Math.max(lastActivity ?? 0, saved.at);
    if (lastActivity === null) { lastActivity = now(); write(keys.activity, { at: lastActivity }); }
    const savedWarning = read(keys.warning);
    const warning = savedWarning?.activityAt === lastActivity && Number.isFinite(savedWarning.deadline) ? savedWarning
      : localWarning?.activityAt === lastActivity ? localWarning : null;
    return { at: lastActivity, deadline: Math.min(lastActivity + timeoutMs, warning?.deadline ?? Infinity), warning };
  }
  function check() {
    if (stopped || expired) return;
    clearTimer(timer);
    const current = snapshot(), remaining = current.deadline - now();
    if (remaining <= 0) {
      expired = true;
      notice(false);
      onExpire();
      return;
    }
    if (current.warning || remaining <= IDLE_WARNING_MS) {
      // The warning belongs to an activity timestamp. A concurrent activity
      // write invalidates an old warning instead of being overwritten by it.
      localWarning = { activityAt: current.at, deadline: current.deadline };
      if (!current.warning || current.warning.deadline > current.deadline) write(keys.warning, localWarning);
      notice(true, Math.ceil(remaining / 1000));
      timer = setTimer(check, Math.min(1000, remaining));
    } else {
      notice(false);
      timer = setTimer(check, remaining - IDLE_WARNING_MS);
    }
  }
  function activity(event) {
    if (stopped || expired || (event && !event.isTrusted) || now() - lastInput < 1000) return;
    lastInput = now();
    check();
    const current = snapshot();
    if (expired || current.warning || current.deadline - now() <= IDLE_WARNING_MS) return;
    lastActivity = now();
    write(keys.activity, { at: lastActivity });
    check();
  }
  function staySignedIn() {
    if (stopped || expired) return;
    check();
    if (expired) return; // An overdue timer after sleep must not revive a session.
    lastActivity = now();
    localWarning = null;
    write(keys.activity, { at: lastActivity });
    remove(keys.warning);
    check();
  }
  const storageChanged = event => { if (!event.key || event.key === keys.activity || event.key === keys.warning) check(); };
  const becameVisible = () => { if (!visibility.hidden) check(); };
  function stop() {
    stopped = true;
    clearTimer(timer);
    INPUT_EVENTS.forEach(event => target.removeEventListener(event, activity, true));
    target.removeEventListener("storage", storageChanged);
    target.removeEventListener("focus", check);
    visibility.removeEventListener("visibilitychange", becameVisible);
  }
  return {
    userId, activity, staySignedIn, check, stop,
    start() {
      stopped = false;
      INPUT_EVENTS.forEach(event => target.addEventListener(event, activity, { passive: true, capture: true }));
      target.addEventListener("storage", storageChanged);
      target.addEventListener("focus", check);
      visibility.addEventListener("visibilitychange", becameVisible);
      check();
    },
    setTimeoutMs(value) { timeoutMs = value; check(); },
    clear() { stop(); remove(keys.activity); remove(keys.warning); },
  };
}
